package mcbot.world;

/**
 * Block-state collision categories for Minecraft 26.3 (protocol 777).
 * Generated from the vanilla 26.3 block registry report.
 * 0 = passable, 1 = solid/blocked, 2 = liquid, 3 = hazard, 4 = climbable.
 */
public final class BlockStateTable {
    public static final byte PASSABLE = 0;
    public static final byte SOLID = 1;
    public static final byte LIQUID = 2;
    public static final byte HAZARD = 3;
    public static final byte CLIMBABLE = 4;

    private static final String DATA =
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "";

    private BlockStateTable() {}

    public static byte category(int stateId) {
        if (stateId < 0 || stateId >= DATA.length()) return SOLID;
        return (byte) (DATA.charAt(stateId) - '0');
    }

    public static boolean passable(int stateId) {
        return category(stateId) == PASSABLE;
    }

    public static boolean solid(int stateId) {
        return category(stateId) == SOLID;
    }
}
